class EventEmitter {
  // ...
  off(event, fn) {
    this.events[event] = this.events[event]?.___(f => f !== fn) ?? [];
  }
}

class EventEmitter {
  once(event, fn) {
    const wrapper = (...args) => {
      fn(...args);
      this.off(event, wrapper);
    };
    this.on(event, wrapper);
  }
}

